class H{int C;boolean P;byte[]v;String s(boolean p,String[]L){P=p;C=L[0].length();int N=L.length*C,n=0;int[][]A=new int[128][N];int[]Z=new int[128];for(int i=0,q;i<N;i++){q=L[i/C].charAt(i%C);if(q>46)A[q][Z[q]++]=i;}v=new byte[N];for(int q=0,i,j;q<128;q++)for(i=0;i<Z[q];i++)for(j=i+1;j<Z[q];j++){int a=A[q][i],b=A[q][j],y=a%C-b%C,z=a-b;g(a,z,y);g(b,-z,-y);}for(byte b:v)n+=b;return n+"";}void g(int a,int z,int y){for(int k=P?1:0,b,c;(b=a+k*z)>=0&b<v.length&(c=a%C+k*y)>=0&c<C;k++){v[b]=1;if(P)return;}}}
